1	param([switch]$Visual, [switch]$Full, [int]$Jobs = 4, [int]$Limit = 1500)
2	# Runs every headless suite, $Jobs at a time. Daily runs sweep fewer generated
3	# floors (each map suite reads DOWNFALL_FULL); -Full sweeps them all.
4	# A suite whose log shows a SCRIPT ERROR is stopped 15 s later 鈥?a SceneTree
5	# script that errors stops but never quits 鈥?and any suite after $Limit s.
6	# Logs go to ../evidence/_suite_<name>.log; a summary is printed at the end.
7	$ErrorActionPreference = 'Stop'
8	$projectPath = Split-Path -Parent $PSScriptRoot
9	$enginePath = Join-Path (Split-Path -Parent $projectPath) 'Godot_v4.7.2-stable_win64_console.exe'
10	if (-not (Test-Path -LiteralPath $enginePath)) { throw "Godot executable not found: $enginePath" }
11	# Suites write their results to ../evidence (res://../evidence); a fresh clone has no such folder.
12	$evidence = Join-Path (Split-Path -Parent $projectPath) 'evidence'
13	New-Item -ItemType Directory -Force -Path $evidence | Out-Null
14	$env:DOWNFALL_FULL = if ($Full) { '1' } else { '' }
15	
16	# Longest first, so the slow map sweeps start at once and the short suites fill in.
17	$headlessSuites = @('test_layout', 'test_siracusa', 'test_siracusa_enemies', 'test_city_variants', 'test_recruit', 'test_traps_traces', 'test_bridges', 'test_elevation', 'test_terrain', 'test_guards', 'test_scene_dressing',
18	    'test_v1', 'test_revisions', 'test_new_enemies', 'test_run_goals', 'test_threat', 'test_base_state', 'test_warehouse', 'test_cases_collectibles', 'test_orders',
19	    'test_medical', 'test_progression', 'test_works', 'test_base_scene', 'test_movement', 'test_combat', 'test_enemy_attacks',
20	    'test_lappland', 'test_amiya', 'test_hellagur', 'test_recruit_kits', 'test_pointer', 'test_prts', 'test_hotbar', 'test_relics', 'test_builds', 'test_inventory', 'test_loot',
21	    'test_item_icons', 'test_relic_icons', 'test_gear', 'test_growth', 'test_gear_expansion', 'test_ai_driver', 'test_audio', 'test_a3_assets', 'test_i18n', 'test_heal_orbs', 'test_prefixes', 'test_prefix_families', 'test_market', 'test_potion_shops', 'test_drag_transfer', 'test_number_fields', 'test_exchange', 'test_packs', 'test_terminal', 'test_voyage', 'test_research', 'test_map_features', 'test_bosses', 'test_arenas', 'test_camera', 'test_specials', 'test_tutorial', 'test_story', 'test_loading_screen', 'test_rhodes_issue', 'test_save_slots', 'test_run_save', 'test_route_map', 'test_elements', 'test_gpu')
22	$visualSuites = @('test_ui_v1', 'test_lappland_input', 'test_amiya_input', 'test_loot_input', 'test_hotbar_input',
23	    'test_base_crew', 'capture_enemy_attacks', 'capture_lappland', 'capture_amiya', 'capture_recruit_kits', 'capture_v1', 'capture_terrain', 'capture_guards', 'capture_bosses', 'capture_arenas')
24	
25	function Invoke-Suites([string[]]$suites, [string[]]$extra, [int]$parallel) {
26	    $queue = [System.Collections.Queue]::new()
27	    foreach ($s in $suites) { $queue.Enqueue($s) }
28	    $running = @{}
29	    $results = [ordered]@{}
30	    while ($queue.Count -gt 0 -or $running.Count -gt 0) {
31	        while ($running.Count -lt $parallel -and $queue.Count -gt 0) {
32	            $suite = $queue.Dequeue()
33	            $log = Join-Path $evidence "_suite_$suite.log"
34	            $arguments = @('--headless', '--path', "`"$projectPath`"", '--script', "res://tests/$suite.gd") + $extra
35	            $process = Start-Process -FilePath $enginePath -ArgumentList $arguments -NoNewWindow -PassThru `
36	                -RedirectStandardOutput $log -RedirectStandardError "$log.err"
37	            # Windows PowerShell only keeps the exit code of a process whose handle was read.
38	            $null = $process.Handle
39	            $running[$suite] = @{ Process = $process; Log = $log; Start = Get-Date; ErrorAt = $null }
40	        }
41	        Start-Sleep -Seconds 2
42	        foreach ($suite in @($running.Keys)) {
43	            $job = $running[$suite]
44	            $text = (Get-Content -LiteralPath $job.Log -Raw -ErrorAction SilentlyContinue) + (Get-Content -LiteralPath "$($job.Log).err" -Raw -ErrorAction SilentlyContinue)
45	            $verdict = $null
46	            if ($job.Process.HasExited) {
47	                $verdict = "exit $($job.Process.ExitCode)"
48	            } else {
49	                if ($null -eq $job.ErrorAt -and $text -match 'SCRIPT ERROR:') { $job.ErrorAt = Get-Date }
50	                if ($null -ne $job.ErrorAt -and ((Get-Date) - $job.ErrorAt).TotalSeconds -ge 15) { $verdict = 'stopped after SCRIPT ERROR' }
51	                elseif (((Get-Date) - $job.Start).TotalSeconds -ge $Limit) { $verdict = "stopped after $Limit s" }
52	                if ($verdict) { Stop-Process -Id $job.Process.Id -Force -ErrorAction SilentlyContinue }
53	            }
54	            if (-not $verdict) { continue }
55	            $failed = ($verdict -ne 'exit 0') -or ($text -match 'SCRIPT ERROR:|FAIL ')
56	            $seconds = [int]((Get-Date) - $job.Start).TotalSeconds
57	            $results[$suite] = @{ Failed = $failed; Verdict = $verdict; Seconds = $seconds }
58	            Write-Host ("{0,-24} {1,-6} {2,5}s  {3}" -f $suite, $(if ($failed) { 'FAIL' } else { 'ok' }), $seconds, $verdict)
59	            if ($failed) { ($text -split "`r?`n") | Where-Object { $_ -match '^FAIL |SCRIPT ERROR:|^\s+at: ' } | Select-Object -First 8 | ForEach-Object { Write-Host "    $_" } }
60	            $running.Remove($suite)
61	        }
62	    }
63	    return $results
64	}
65	
66	$started = Get-Date
67	$all = Invoke-Suites $headlessSuites @() $Jobs
68	if ($Visual) {
69	    # Rendered suites draw to a window: one at a time.
70	    $more = Invoke-Suites $visualSuites @('--rendering-method', 'gl_compatibility', '--audio-driver', 'Dummy', '--resolution', '1280x720') 1
71	    foreach ($key in $more.Keys) { $all[$key] = $more[$key] }
72	}
73	$bad = @($all.Keys | Where-Object { $all[$_].Failed })
74	Write-Output ("{0} suites in {1:n0} s ({2}), {3} failed" -f $all.Count, ((Get-Date) - $started).TotalSeconds, $(if ($Full) { 'full' } else { 'daily' }), $bad.Count)
75	if ($bad.Count -gt 0) { throw "Failed: $($bad -join ', ')" }
76

